export const blocks: readonly LiturgyBlock[] = [
  {"id": "ru-pes-0001", "section": "service", "who": "rubric", "text": "Песни священного писания праздничные"},
  {"id": "ru-pes-0002", "section": "service", "who": "rubric", "text": "Песнь 1"},
  {"id": "ru-pes-0003", "section": "service", "who": "rubric", "text": "Под воскресенье ирмос и 1-й тропарь с припевом:"},
  {"id": "ru-pes-0004", "section": "service", "who": "reader", "text": "Слава, Господи, святому Воскресению Твоему."},
  {"id": "ru-pes-0005", "section": "service", "who": "rubric", "text": "В праздники ирмос дважды."},
  {"id": "ru-pes-0006", "section": "service", "who": "rubric", "text": "на 12:"},
  {"id": "ru-pes-0007", "section": "service", "who": "reader", "text": "Воспоём Господу, ибо Он славно прославился; / коня и всадника ввергнул в море."},
  {"id": "ru-pes-0008", "section": "service", "who": "reader", "text": "Помощник и Покровитель стал мне спасением; / Он – Бог мой, и прославлю Его, / Бог отца моего, и превознесу Его. на 10:"},
  {"id": "ru-pes-0009", "section": "service", "who": "reader", "text": "Господь, сокрушающий в битвах, / Господь – имя Ему. / Колесницы фараона и войско его ввергнул Он в море."},
  {"id": "ru-pes-0010", "section": "service", "who": "reader", "text": "Пучиною покрыл их, / они погрузились в глубину, как камень. на 8:"},
  {"id": "ru-pes-0011", "section": "service", "who": "reader", "text": "Тогда заспешили вожди Эдома / и князья Моавитян, объял их трепет, / изнемогли все жители Ханаана."},
  {"id": "ru-pes-0012", "section": "service", "who": "reader", "text": "Да нападёт на них страх и трепет; / от величия мышцы Твоей да станут они, как камень. на 6:"},
  {"id": "ru-pes-0013", "section": "service", "who": "reader", "text": "Доколе не пройдёт народ Твой, Господи, / доколе не пройдёт народ Твой сей, который Ты приобрёл."},
  {"id": "ru-pes-0014", "section": "service", "who": "reader", "text": "Устроил Ты, Господи, святыню, / Господи, которую приготовили руки Твои. на 4:"},
  {"id": "ru-pes-0015", "section": "service", "who": "reader", "text": "Господь царствует вечно: и навек, и дальше. / Когда вошел конь фараона с колесницами и всадниками в море."},
  {"id": "ru-pes-0016", "section": "service", "who": "reader", "text": "Сыны же Израилевы прошли по суше / посреди моря. Исх 15:1–5, 15–19"},
  {"id": "ru-pes-0017", "section": "service", "who": "reader", "text": "Слава Отцу, и Сыну, и Святому Духу."},
  {"id": "ru-pes-0018", "section": "service", "who": "reader", "text": "И ныне, и всегда, и во веки веков. Аминь. Катавасия"},
  {"id": "ru-pes-0019", "section": "service", "who": "rubric", "text": "Песнь 3"},
  {"id": "ru-pes-0020", "section": "service", "who": "rubric", "text": "Ирмос"},
  {"id": "ru-pes-0021", "section": "service", "who": "reader", "text": "Слава, Господи, святому Воскресению Твоему. на 12:"},
  {"id": "ru-pes-0022", "section": "service", "who": "reader", "text": "Утвердилось сердце моё в Господе, / вознесся рог мой в Боге моём, / широко раскрылись на врагов моих уста мои: / я радуюсь о спасении Твоём."},
  {"id": "ru-pes-0023", "section": "service", "who": "reader", "text": "Ибо нет святого, как Господь, / и нет праведного, как Бог наш, / и нет святого, кроме Тебя. на 10:"},
  {"id": "ru-pes-0024", "section": "service", "who": "reader", "text": "Не хвалитесь и не говорите высокого в гордыне, / речь надменная да не выйдет из уст ваших."},
  {"id": "ru-pes-0025", "section": "service", "who": "reader", "text": "Ибо Бог ведения Господь, / и Бог, уготовляющий дела Свои. на 8:"},
  {"id": "ru-pes-0026", "section": "service", "who": "reader", "text": "Даёт молитву молящемуся / и благословляет годы праведного."},
  {"id": "ru-pes-0027", "section": "service", "who": "reader", "text": "Господь сделает немощным противника Своего, / Господь свят. на 6:"},
  {"id": "ru-pes-0028", "section": "service", "who": "reader", "text": "Да не хвалится мудрый мудростью своею, / и да не хвалится сильный силою своею, / и да не хвалится богатый богатством своим."},
  {"id": "ru-pes-0029", "section": "service", "who": "reader", "text": "Но лишь тем да хвалится хвалящийся, / что разумеет и знает Господа / и творит суд и правду посреди земли. на 4:"},
  {"id": "ru-pes-0030", "section": "service", "who": "reader", "text": "Господь взошёл на небеса и возгремел, / Он, праведный, будет судить концы земли."},
  {"id": "ru-pes-0031", "section": "service", "who": "reader", "text": "И даст мощь царю нашему, / и возвысит рог помазанника Своего. 1 Цар 2:1-3, 9-10"},
  {"id": "ru-pes-0032", "section": "service", "who": "reader", "text": "Слава: И ныне: Катавасия"},
  {"id": "ru-pes-0033", "section": "service", "who": "rubric", "text": "Песнь 4"},
  {"id": "ru-pes-0034", "section": "service", "who": "rubric", "text": "Ирмос"},
  {"id": "ru-pes-0035", "section": "service", "who": "reader", "text": "Слава, Господи, святому Воскресению Твоему. на 12:"},
  {"id": "ru-pes-0036", "section": "service", "who": "reader", "text": "Господи, услышал я весть Твою – и убоялся, / уразумел дела Твои – и изумился."},
  {"id": "ru-pes-0037", "section": "service", "who": "reader", "text": "Когда смущена душа моя – / во гневе вспомнишь о милости. на 10:"},
  {"id": "ru-pes-0038", "section": "service", "who": "reader", "text": "Бог от Фемана придёт, / и Святой – от горы [Фаран,] осененной чащей."},
  {"id": "ru-pes-0039", "section": "service", "who": "reader", "text": "Покрыла небеса доблесть Его, / и хвалы Его полна земля. на 8:"},
  {"id": "ru-pes-0040", "section": "service", "who": "reader", "text": "Ибо смоковница не принесёт плода, / и не будет плода на виноградных лозах."},
  {"id": "ru-pes-0041", "section": "service", "who": "reader", "text": "Обманет произведение маслины, / и поля не принесут пищи. на 6:"},
  {"id": "ru-pes-0042", "section": "service", "who": "reader", "text": "Без еды остались овцы, / и нет волов у яслей."},
  {"id": "ru-pes-0043", "section": "service", "who": "reader", "text": "Я же возрадуюсь о Господе, / возвеселюсь в Боге, Спасителе моём. на 4:"},
  {"id": "ru-pes-0044", "section": "service", "who": "reader", "text": "Господь, Бог мой – сила моя, / и направит Он ноги мои к совершенству."},
  {"id": "ru-pes-0045", "section": "service", "who": "reader", "text": "И на высоты возведёт меня, / чтобы победить мне, воспевая Его. Авв 3:2–3, 17–19"},
  {"id": "ru-pes-0046", "section": "service", "who": "reader", "text": "Слава: И ныне: Катавасия"},
  {"id": "ru-pes-0047", "section": "service", "who": "rubric", "text": "Песнь 5"},
  {"id": "ru-pes-0048", "section": "service", "who": "rubric", "text": "Ирмос"},
  {"id": "ru-pes-0049", "section": "service", "who": "reader", "text": "Слава, Господи, святому Воскресению Твоему. на 12:"},
  {"id": "ru-pes-0050", "section": "service", "who": "reader", "text": "От ночи с рассвета стремится дух мой к Тебе, Боже, / ибо свет – повеления Твои на земле."},
  {"id": "ru-pes-0051", "section": "service", "who": "reader", "text": "Правде научитесь, живущие на земле. на 10:"},
  {"id": "ru-pes-0052", "section": "service", "who": "reader", "text": "Пусть сгинет нечестивец, да не видит славы Господа. / Господи, высока Твоя мышца, и они не познали; / но, уразумев, устыдятся."},
  {"id": "ru-pes-0053", "section": "service", "who": "reader", "text": "Ревность постигнет народ не наставленный, / и ныне противников поглотит огонь. на 8:"},
  {"id": "ru-pes-0054", "section": "service", "who": "reader", "text": "Прибавь бедствий им, Господи, / прибавь бедствий славным земли."},
  {"id": "ru-pes-0055", "section": "service", "who": "reader", "text": "Господи, в скорби я вспомнил Тебя, / в скорби краткой вразумление Твоё нам. на 6:"},
  {"id": "ru-pes-0056", "section": "service", "who": "reader", "text": "И как рождающая приближается к родам / и в муке своей возопила, / так мы стали для Возлюбленного Твоего."},
  {"id": "ru-pes-0057", "section": "service", "who": "reader", "text": "Не падём, но падут живущие на земле. на 4:"},
  {"id": "ru-pes-0058", "section": "service", "who": "reader", "text": "Воскреснут мёртвые, и восстанут находящиеся в гробницах, / и возвеселятся живущие на земле."},
  {"id": "ru-pes-0059", "section": "service", "who": "reader", "text": "Ибо роса, что от Тебя, – исцеление для них, / земля же нечестивых падёт. Ис 26:9, 11, 15–19"},
  {"id": "ru-pes-0060", "section": "service", "who": "reader", "text": "Слава: И ныне: Катавасия"},
  {"id": "ru-pes-0061", "section": "service", "who": "rubric", "text": "Песнь 6"},
  {"id": "ru-pes-0062", "section": "service", "who": "rubric", "text": "Ирмос"},
  {"id": "ru-pes-0063", "section": "service", "who": "reader", "text": "Слава, Господи, святому Воскресению Твоему. на 12:"},
  {"id": "ru-pes-0064", "section": "service", "who": "reader", "text": "Возопил я в скорби моей к Господу, Богу моему, / и Он услышал меня."},
  {"id": "ru-pes-0065", "section": "service", "who": "reader", "text": "Ты отринул меня в глубины, в сердце моря, / и реки окружили меня. на 10:"},
  {"id": "ru-pes-0066", "section": "service", "who": "reader", "text": "Все валы Твои и волны Твои прошли надо мною."},
  {"id": "ru-pes-0067", "section": "service", "who": "reader", "text": "Придётся ли мне ещё взглянуть на храм святой Твой? на 8:"},
  {"id": "ru-pes-0068", "section": "service", "who": "reader", "text": "Разлилась вокруг меня вода до души моей, / окружила меня бездна глубочайшая."},
  {"id": "ru-pes-0069", "section": "service", "who": "reader", "text": "Погрузилась голова моя в расселины гор, / сошёл я в землю, чьи засовы – преграды вечные. на 6:"},
  {"id": "ru-pes-0070", "section": "service", "who": "reader", "text": "Но да взойдёт от гибели жизнь моя к Тебе, Господи, Боже мой!"},
  {"id": "ru-pes-0071", "section": "service", "who": "reader", "text": "И да придёт к Тебя молитва моя, в храм святой Твой! на 4:"},
  {"id": "ru-pes-0072", "section": "service", "who": "reader", "text": "Соблюдающие суетное и ложное милость свою оставили."},
  {"id": "ru-pes-0073", "section": "service", "who": "reader", "text": "Я же всё, что обещал, воздам Тебе, о спасении моём – Господу! Ион 2:3–10"},
  {"id": "ru-pes-0074", "section": "service", "who": "reader", "text": "Слава: И ныне: Катавасия"},
  {"id": "ru-pes-0075", "section": "service", "who": "rubric", "text": "Песнь 7"},
  {"id": "ru-pes-0076", "section": "service", "who": "rubric", "text": "Ирмос"},
  {"id": "ru-pes-0077", "section": "service", "who": "reader", "text": "Слава, Господи, святому Воскресению Твоему. на 12:"},
  {"id": "ru-pes-0078", "section": "service", "who": "reader", "text": "Благословен Ты, Господи Боже отцов наших, / и хвально и прославлено имя Твое вовеки."},
  {"id": "ru-pes-0079", "section": "service", "who": "reader", "text": "И все дела Твои истинны, и правы пути Твои. на 10:"},
  {"id": "ru-pes-0080", "section": "service", "who": "reader", "text": "И все суды Твои истинны, / и суды истинные Ты сотворил."},
  {"id": "ru-pes-0081", "section": "service", "who": "reader", "text": "И на святой град отцов наших Иерусалим. на 8:"},
  {"id": "ru-pes-0082", "section": "service", "who": "reader", "text": "Благословен Ты, Господи, Боже отцов наших, / и хвальный и превозносимый вовеки."},
  {"id": "ru-pes-0083", "section": "service", "who": "reader", "text": "И благословенно имя славы Твоей, святое / и прехвальное и превозносимое вовеки. на 6:"},
  {"id": "ru-pes-0084", "section": "service", "who": "reader", "text": "Благословен Ты в храме святой славы Твоей, / и прехвальный и преславный вовеки."},
  {"id": "ru-pes-0085", "section": "service", "who": "reader", "text": "Благословен Ты, видящий бездны, восседающий на Херувимах, / и прехвальный и превозносимый вовеки. на 4:"},
  {"id": "ru-pes-0086", "section": "service", "who": "reader", "text": "Благословен Ты на престоле славы Царства Твоего, / и прехвальный и превозносимый вовеки."},
  {"id": "ru-pes-0087", "section": "service", "who": "reader", "text": "Благословен Ты на тверди небесной, / и прехвальный и преславный вовеки. Дан 3:26–28, 52–56"},
  {"id": "ru-pes-0088", "section": "service", "who": "reader", "text": "Слава: И ныне: Катавасия"},
  {"id": "ru-pes-0089", "section": "service", "who": "rubric", "text": "Песнь 8"},
  {"id": "ru-pes-0090", "section": "service", "who": "rubric", "text": "Ирмос"},
  {"id": "ru-pes-0091", "section": "service", "who": "reader", "text": "Слава, Господи, святому Воскресению Твоему. на 12:"},
  {"id": "ru-pes-0092", "section": "service", "who": "reader", "text": "Благословляйте, все творения Господни, Господа, / пойте и превозносите Его вовеки."},
  {"id": "ru-pes-0093", "section": "service", "who": "reader", "text": "Благословляйте, Ангелы Господни, небеса Господни, Господа, / пойте и превозносите Его вовеки. на 10:"},
  {"id": "ru-pes-0094", "section": "service", "who": "reader", "text": "Благословляйте, все воды, что превыше небес, все силы Господни, Господа, / пойте и превозносите Его вовеки."},
  {"id": "ru-pes-0095", "section": "service", "who": "reader", "text": "Благословляйте, солнце и луна, звёзды небесные, Господа, / пойте и превозносите Его вовеки. на 8:"},
  {"id": "ru-pes-0096", "section": "service", "who": "reader", "text": "Благословляйте, все птицы небесные, звери и весь скот, Господа, / пойте и превозносите Его вовеки."},
  {"id": "ru-pes-0097", "section": "service", "who": "reader", "text": "Благословляйте, сыны человеческие, / да благословляет Израиль Господа, / пойте и превозносите Его вовеки. на 6:"},
  {"id": "ru-pes-0098", "section": "service", "who": "reader", "text": "Благословляйте, священники Господни, рабы Господни, Господа, / пойте и превозносите Его вовеки."},
  {"id": "ru-pes-0099", "section": "service", "who": "reader", "text": "Благословляйте, духи и души праведных, / благоговейные и смиренные сердцем, Господа, / пойте и превозносите Его вовеки. на 4:"},
  {"id": "ru-pes-0100", "section": "service", "who": "reader", "text": "Благословляйте, Анания, Азария и Мисаил, Господа, / пойте и превозносите Его вовеки. Дан 3:57, 58, 60, 62, 80, 82, 84, 86, 88"},
  {"id": "ru-pes-0101", "section": "service", "who": "reader", "text": "Благословляйте, Апостолы, пророки и мученики Господни, Господа / пойте и превозносите Его вовеки."},
  {"id": "ru-pes-0102", "section": "service", "who": "reader", "text": "Благословим Отца, и Сына, и Святого Духа Господа."},
  {"id": "ru-pes-0103", "section": "service", "who": "reader", "text": "И ныне, и всегда и вовеки веков. Аминь."},
  {"id": "ru-pes-0104", "section": "service", "who": "reader", "text": "Хвалим, благословляем, поклоняемся Господу, воспевая и превознося Его во все века. Катавасия"},
  {"id": "ru-pes-0105", "section": "service", "who": "rubric", "text": "Песнь 9"},
  {"id": "ru-pes-0106", "section": "service", "who": "reader", "text": "Величает душа Моя Господа, / и возрадовался дух Мой о Боге, Спасителе Моём."},
  {"id": "ru-pes-0107", "section": "service", "who": "reader", "text": "Честью высшую Херувимов / и несравненно славнейшую Серафимов, / девственно Бога-Слово родившую, / истинную Богородицу – Тебя величаем."},
  {"id": "ru-pes-0108", "section": "service", "who": "rubric", "text": "– повторяем после каждого стиха."},
  {"id": "ru-pes-0109", "section": "service", "who": "reader", "text": "Что призрел Он на смирение Рабы Своей; / ибо отныне назовут Меня блаженной все роды."},
  {"id": "ru-pes-0110", "section": "service", "who": "reader", "text": "Что сотворил Мне великое Сильный, / и свято имя Его, / и милость Его в роды родов к боящимся Его."},
  {"id": "ru-pes-0111", "section": "service", "who": "reader", "text": "Соделал Он сильное рукою Своею, / рассеял надменных в помышлениях сердца их."},
  {"id": "ru-pes-0112", "section": "service", "who": "reader", "text": "Низложил властителей с престолов / и вознёс смиренных, / алчущих исполнил благ / и богатых отослал ни с чем."},
  {"id": "ru-pes-0113", "section": "service", "who": "reader", "text": "Поддержал Израиля, отрока Своего, вспомнив о милости, – / как Он сказал отцам нашим, – / к Аврааму и семени его навеки. Лк 1:46–55 Ирмос"},
  {"id": "ru-pes-0114", "section": "service", "who": "reader", "text": "Слава, Господи, святому Воскресению Твоему. на 12:"},
  {"id": "ru-pes-0115", "section": "service", "who": "reader", "text": "Благословен Господь, Бог Израилев, / что посетил и сотворил искупление народу Своему."},
  {"id": "ru-pes-0116", "section": "service", "who": "reader", "text": "И воздвиг рог спасения нам / в доме Давида, отрока Своего. на 10:"},
  {"id": "ru-pes-0117", "section": "service", "who": "reader", "text": "Как Он сказал устами святых, бывших от века пророков Своих, – / спасение от врагов наших / и от руки всех ненавидящих нас."},
  {"id": "ru-pes-0118", "section": "service", "who": "reader", "text": "Сотворить милость отцам нашим / и вспомнить завет Свой святой. на 8:"},
  {"id": "ru-pes-0119", "section": "service", "who": "reader", "text": "Клятву, которою Он клялся Аврааму, отцу нашему, / дать нам безбоязненно, от рук врагов наших избавившимся."},
  {"id": "ru-pes-0120", "section": "service", "who": "reader", "text": "Служить Ему в святости и правде / пред Ним во все дни жизни нашей. на 6:"},
  {"id": "ru-pes-0121", "section": "service", "who": "reader", "text": "И ты, дитя, пророком Всевышнего будешь названо, / ибо ты будешь идти пред лицом Господа – приготовить пути Ему."},
  {"id": "ru-pes-0122", "section": "service", "who": "reader", "text": "Дать народу Его познать спасение / в отпущении грехов их, / по глубине милосердия Бога нашего. на 4:"},
  {"id": "ru-pes-0123", "section": "service", "who": "reader", "text": "Которым с высоты посетит нас Восходящее Светило, / чтобы воссиять сидящим во тьме и тени смертной."},
  {"id": "ru-pes-0124", "section": "service", "who": "reader", "text": "Направить ноги наши на путь мира. Лк 1:68-79"},
  {"id": "ru-pes-0125", "section": "service", "who": "reader", "text": "Слава: И ныне: Катавасия"},
  {"id": "ru-pes-0126", "section": "service", "who": "rubric", "text": "Песни священного писания вседневные"},
  {"id": "ru-pes-0127", "section": "service", "who": "rubric", "text": "Песнь 1"},
  {"id": "ru-pes-0128", "section": "service", "who": "reader", "text": "Воспоём Господу, ибо Он славно прославился; / коня и всадника ввергнул в море."},
  {"id": "ru-pes-0129", "section": "service", "who": "reader", "text": "Помощник и Покровитель стал мне спасением; / Он – Бог мой, и прославлю Его, / Бог отца моего, и превознесу Его."},
  {"id": "ru-pes-0130", "section": "service", "who": "reader", "text": "Господь, сокрушающий в битвах, / Господь – имя Ему. / Колесницы фараона и войско его ввергнул Он в море."},
  {"id": "ru-pes-0131", "section": "service", "who": "reader", "text": "Пучиною покрыл их, / они погрузились в глубину, как камень. на 14:"},
  {"id": "ru-pes-0132", "section": "service", "who": "reader", "text": "Застыли воды, как стена, / застыли и волны посреди моря. Ирмос"},
  {"id": "ru-pes-0133", "section": "service", "who": "reader", "text": "Сказал враг: «Погонюсь, настигну, / разделю добычу, насыщу душу мою, / убью мечём моим, господствовать будет рука моя». на 12:"},
  {"id": "ru-pes-0134", "section": "service", "who": "reader", "text": "Ты послал Дух Твой, покрыло их море, / погрузились они, как свинец, в воде великой."},
  {"id": "ru-pes-0135", "section": "service", "who": "reader", "text": "Кто подобен Тебе среди богов, Господи? / Кто подобен Тебе, прославленный среди святых, / дивный в славе, творящий чудеса? на 10:"},
  {"id": "ru-pes-0136", "section": "service", "who": "reader", "text": "Ты простер десницу Твою, – / поглотила их земля. / Ты повёл по правде Твоей этот народ Твой, который Ты искупил."},
  {"id": "ru-pes-0137", "section": "service", "who": "reader", "text": "Призвал силою Твоею во обитель святую Твою. / Услышали народы, и разгневались, / муки объяли жителей Филистимских. на 8:"},
  {"id": "ru-pes-0138", "section": "service", "who": "reader", "text": "Тогда заспешили вожди Эдома / и князья Моавитян, объял их трепет, / изнемогли все жители Ханаана."},
  {"id": "ru-pes-0139", "section": "service", "who": "reader", "text": "Да нападёт на них страх и трепет; / от величия мышцы Твоей да станут они, как камень. на 6:"},
  {"id": "ru-pes-0140", "section": "service", "who": "reader", "text": "Доколе не пройдёт народ Твой, Господи, / доколе не пройдёт народ Твой сей, который Ты приобрёл."},
  {"id": "ru-pes-0141", "section": "service", "who": "reader", "text": "Устроил Ты, Господи, / святыню, Господи, которую приготовили руки Твои. на 4:"},
  {"id": "ru-pes-0142", "section": "service", "who": "reader", "text": "Господь царствует вечно: и навек, и дальше. / Когда вошел конь фараона с колесницами и всадниками в море."},
  {"id": "ru-pes-0143", "section": "service", "who": "reader", "text": "Сыны же Израилевы прошли по суше посреди моря. Исх 15:1–19"},
  {"id": "ru-pes-0144", "section": "service", "who": "reader", "text": "Слава: И ныне:"},
  {"id": "ru-pes-0145", "section": "service", "who": "rubric", "text": "Песнь 3"},
  {"id": "ru-pes-0146", "section": "service", "who": "reader", "text": "Утвердилось сердце моё в Господе, / вознесся рог мой в Боге моём, / широко раскрылись на врагов моих уста мои: / я радуюсь о спасении Твоём."},
  {"id": "ru-pes-0147", "section": "service", "who": "reader", "text": "Ибо нет святого, как Господь, / и нет праведного, как Бог наш, / и нет святого, кроме Тебя."},
  {"id": "ru-pes-0148", "section": "service", "who": "reader", "text": "Не хвалитесь и не говорите высокого в гордыне, / речь надменная да не выйдет из уст ваших."},
  {"id": "ru-pes-0149", "section": "service", "who": "reader", "text": "Ибо Бог ведения Господь, / и Бог, уготовляющий дела Свои. на 14:"},
  {"id": "ru-pes-0150", "section": "service", "who": "reader", "text": "Лук сильных ослабел, / а немощные препоясались силою. Ирмос"},
  {"id": "ru-pes-0151", "section": "service", "who": "reader", "text": "Насыщенные хлебом оскудели, / а алчущие заселили землю. на 12:"},
  {"id": "ru-pes-0152", "section": "service", "who": "reader", "text": "Ибо неплодная родила семерых, / а многодетная изнемогла."},
  {"id": "ru-pes-0153", "section": "service", "who": "reader", "text": "Господь умерщвляет и животворит, / низводит во ад и возводит. на 10:"},
  {"id": "ru-pes-0154", "section": "service", "who": "reader", "text": "Господь делает нищим и обогащает, / унижает и возвышает, / поднимает с земли бедного, / и из грязи воздвигает нищего."},
  {"id": "ru-pes-0155", "section": "service", "who": "reader", "text": "Чтобы посадить его с властителями народа, / и престол славы давая в наследие ему. на 8:"},
  {"id": "ru-pes-0156", "section": "service", "who": "reader", "text": "Даёт молитву молящемуся / и благословляет годы праведного."},
  {"id": "ru-pes-0157", "section": "service", "who": "reader", "text": "Господь сделает немощным противника Своего, / Господь свят. на 6:"},
  {"id": "ru-pes-0158", "section": "service", "who": "reader", "text": "Да не хвалится мудрый мудростью своею, / и да не хвалится сильный силою своею, / и да не хвалится богатый богатством своим."},
  {"id": "ru-pes-0159", "section": "service", "who": "reader", "text": "И творит суд и правду посреди земли. на 4:"},
  {"id": "ru-pes-0160", "section": "service", "who": "reader", "text": "Господь взошёл на небеса и возгремел, / Он, праведный, будет судить концы земли."},
  {"id": "ru-pes-0161", "section": "service", "who": "reader", "text": "И даст мощь царю нашему, / и возвысит рог помазанника Своего. 1 Цар 2:1–10"},
  {"id": "ru-pes-0162", "section": "service", "who": "reader", "text": "Слава: И ныне: Катавасия"},
  {"id": "ru-pes-0163", "section": "service", "who": "rubric", "text": "Песнь 4"},
  {"id": "ru-pes-0164", "section": "service", "who": "reader", "text": "Господи, услышал я весть Твою – и убоялся, / уразумел дела Твои – и изумился."},
  {"id": "ru-pes-0165", "section": "service", "who": "reader", "text": "Когда смущена душа моя – во гневе вспомнишь о милости."},
  {"id": "ru-pes-0166", "section": "service", "who": "reader", "text": "Бог от Фемана придёт, / и Святой – от горы [Фаран,] осененной чащей."},
  {"id": "ru-pes-0167", "section": "service", "who": "reader", "text": "Покрыла небеса доблесть Его, / и хвалы Его полна земля. на 14:"},
  {"id": "ru-pes-0168", "section": "service", "who": "reader", "text": "Бросил в головы беззаконных смерть, / воздвиг им узы до шеи. Ирмос"},
  {"id": "ru-pes-0169", "section": "service", "who": "reader", "text": "Рассек в исступлении головы властителей; / они содрогнутся при этом: / раскроют узды свои, / как нищий, поедающий скрытно. на 12:"},
  {"id": "ru-pes-0170", "section": "service", "who": "reader", "text": "И возвёл Ты на море коней Твоих, / волнующих воды многие."},
  {"id": "ru-pes-0171", "section": "service", "who": "reader", "text": "Я укрылся, и устрашилась внутренность моя / от гласа молитвы губ моих. на 10:"},
  {"id": "ru-pes-0172", "section": "service", "who": "reader", "text": "И вошел трепет в кости мои, / и во мне сотряслась крепость моя."},
  {"id": "ru-pes-0173", "section": "service", "who": "reader", "text": "Отдохну я в день скорби моей, / чтобы придти мне к народу, с которым странствую я. на 8:"},
  {"id": "ru-pes-0174", "section": "service", "who": "reader", "text": "Ибо смоковница не принесёт плода, / и не будет плода на виноградных лозах."},
  {"id": "ru-pes-0175", "section": "service", "who": "reader", "text": "Обманет произведение маслины, / и поля не принесут пищи. на 6:"},
  {"id": "ru-pes-0176", "section": "service", "who": "reader", "text": "Без еды остались овцы, / и нет волов у яслей."},
  {"id": "ru-pes-0177", "section": "service", "who": "reader", "text": "Я же возрадуюсь о Господе, / возвеселюсь в Боге, Спасителе моём. на 4:"},
  {"id": "ru-pes-0178", "section": "service", "who": "reader", "text": "Господь, Бог мой – сила моя, / и направит Он ноги мои к совершенству."},
  {"id": "ru-pes-0179", "section": "service", "who": "reader", "text": "И на высоты возведёт меня, / чтобы победить мне, воспевая Его. Авв 3:2–3, 13–19"},
  {"id": "ru-pes-0180", "section": "service", "who": "reader", "text": "Слава: И ныне:"},
  {"id": "ru-pes-0181", "section": "service", "who": "rubric", "text": "Песнь 5"},
  {"id": "ru-pes-0182", "section": "service", "who": "reader", "text": "От ночи с рассвета стремится дух мой к Тебе, Боже, / ибо свет – повеления Твои на земле."},
  {"id": "ru-pes-0183", "section": "service", "who": "reader", "text": "Правде научитесь, живущие на земле. на 14:"},
  {"id": "ru-pes-0184", "section": "service", "who": "reader", "text": "Господи, высока Твоя мышца, и они не познали; / но, уразумев, устыдятся. Ирмос"},
  {"id": "ru-pes-0185", "section": "service", "who": "reader", "text": "Ревность постигнет народ не наставленный, / и ныне противников поглотит огонь. на 12:"},
  {"id": "ru-pes-0186", "section": "service", "who": "reader", "text": "Господи, Боже наш, мир дай нам, / ибо всё Ты воздал нам."},
  {"id": "ru-pes-0187", "section": "service", "who": "reader", "text": "Господи Боже наш, возьми во владение нас; / Господи, кроме Тебя, мы иного не знаем, / имя Твоё именуем. на 10:"},
  {"id": "ru-pes-0188", "section": "service", "who": "reader", "text": "А мёртвые жизни не увидят, / и врачи их не воскресят."},
  {"id": "ru-pes-0189", "section": "service", "who": "reader", "text": "Потому Ты навел гнев, и погубил, / и уничтожил весь мужской пол их. на 8:"},
  {"id": "ru-pes-0190", "section": "service", "who": "reader", "text": "Прибавь бедствий им, Господи, / прибавь бедствий славным земли."},
  {"id": "ru-pes-0191", "section": "service", "who": "reader", "text": "Господи, в скорби я вспомнил Тебя, / в скорби краткой вразумление Твоё нам. на 6:"},
  {"id": "ru-pes-0192", "section": "service", "who": "reader", "text": "И как рождающая приближается к родам / и в муке своей возопила, / так мы стали для Возлюбленного Твоего."},
  {"id": "ru-pes-0193", "section": "service", "who": "reader", "text": "Не падём, но падут живущие на земле. на 4:"},
  {"id": "ru-pes-0194", "section": "service", "who": "reader", "text": "Воскреснут мёртвые, и восстанут находящиеся в гробницах, / и возвеселятся живущие на земле."},
  {"id": "ru-pes-0195", "section": "service", "who": "reader", "text": "Ибо роса, что от Тебя, – исцеление для них, / земля же нечестивых падёт. Ис 26:9, 11–19"},
  {"id": "ru-pes-0196", "section": "service", "who": "reader", "text": "Слава: И ныне:"},
  {"id": "ru-pes-0197", "section": "service", "who": "rubric", "text": "Песнь 6"},
  {"id": "ru-pes-0198", "section": "service", "who": "rubric", "text": "Ирмос. Тропарь первый без стиха."},
  {"id": "ru-pes-0199", "section": "service", "who": "rubric", "text": "на 12:"},
  {"id": "ru-pes-0200", "section": "service", "who": "reader", "text": "Возопил я в скорби моей к Господу, Богу моему, / и Он услышал меня;"},
  {"id": "ru-pes-0201", "section": "service", "who": "reader", "text": "Ты отринул меня в глубины, в сердце моря, / и реки окружили меня. на 10:"},
  {"id": "ru-pes-0202", "section": "service", "who": "reader", "text": "Все валы Твои и волны Твои прошли надо мною."},
  {"id": "ru-pes-0203", "section": "service", "who": "reader", "text": "Придётся ли мне ещё взглянуть на храм святой Твой? на 8:"},
  {"id": "ru-pes-0204", "section": "service", "who": "reader", "text": "Разлилась вокруг меня вода до души моей, / окружила меня бездна глубочайшая."},
  {"id": "ru-pes-0205", "section": "service", "who": "reader", "text": "Погрузилась голова моя в расселины гор, / сошёл я в землю, чьи засовы – преграды вечные. на 6:"},
  {"id": "ru-pes-0206", "section": "service", "who": "reader", "text": "Но да взойдёт от гибели жизнь моя к Тебе, Господи, Боже мой."},
  {"id": "ru-pes-0207", "section": "service", "who": "reader", "text": "И да придёт к Тебя молитва моя, в храм святой Твой. на 4:"},
  {"id": "ru-pes-0208", "section": "service", "who": "reader", "text": "Соблюдающие суетное и ложное милость свою оставили."},
  {"id": "ru-pes-0209", "section": "service", "who": "reader", "text": "Всё, что обещал, воздам Тебе, о спасении моём – Господу! Ион 2:3–10"},
  {"id": "ru-pes-0210", "section": "service", "who": "reader", "text": "Слава: И ныне: Катавасия"},
  {"id": "ru-pes-0211", "section": "service", "who": "rubric", "text": "Песнь 7"},
  {"id": "ru-pes-0212", "section": "service", "who": "rubric", "text": "Ирмос. Тропарь первый без стиха."},
  {"id": "ru-pes-0213", "section": "service", "who": "rubric", "text": "на 12:"},
  {"id": "ru-pes-0214", "section": "service", "who": "reader", "text": "Благословен Ты, Господи Боже отцов наших, / и хвально и прославлено имя Твое вовеки."},
  {"id": "ru-pes-0215", "section": "service", "who": "reader", "text": "И все дела Твои истинны, и правы пути Твои. на 10:"},
  {"id": "ru-pes-0216", "section": "service", "who": "reader", "text": "И все суды Твои истинны, и суды истинные Ты сотворил."},
  {"id": "ru-pes-0217", "section": "service", "who": "reader", "text": "И на святой град отцов наших Иерусалим. на 8:"},
  {"id": "ru-pes-0218", "section": "service", "who": "reader", "text": "Благословен Ты, Господи, Боже отцов наших, / и хвальный и превозносимый вовеки."},
  {"id": "ru-pes-0219", "section": "service", "who": "reader", "text": "И благословенно имя славы Твоей, святое / и прехвальное и превозносимое вовеки. на 6:"},
  {"id": "ru-pes-0220", "section": "service", "who": "reader", "text": "Благословен Ты в храме святой славы Твоей, / и прехвальный и преславный вовеки."},
  {"id": "ru-pes-0221", "section": "service", "who": "reader", "text": "Благословен Ты, видящий бездны, восседающий на Херувимах, / и прехвальный и превозносимый вовеки. на 4:"},
  {"id": "ru-pes-0222", "section": "service", "who": "reader", "text": "Благословен Ты на престоле славы Царства Твоего, / и прехвальный и превозносимый вовеки."},
  {"id": "ru-pes-0223", "section": "service", "who": "reader", "text": "Благословен Ты на тверди небесной, / и прехвальный и преславный вовеки. Дан 3:26–28; 52–56"},
  {"id": "ru-pes-0224", "section": "service", "who": "reader", "text": "Слава: И ныне:"},
  {"id": "ru-pes-0225", "section": "service", "who": "rubric", "text": "Песнь 8"},
  {"id": "ru-pes-0226", "section": "service", "who": "reader", "text": "Благословляйте, все творения Господни, Господа, / пойте и превозносите Его вовеки."},
  {"id": "ru-pes-0227", "section": "service", "who": "reader", "text": "Благословляйте, Ангелы Господни, небеса Господни, Господа, / пойте и превозносите Его вовеки."},
  {"id": "ru-pes-0228", "section": "service", "who": "reader", "text": "Благословляйте, все воды, что превыше небес, все силы Господни, Господа, / пойте и превозносите Его вовеки."},
  {"id": "ru-pes-0229", "section": "service", "who": "reader", "text": "Благословляйте, солнце и луна, звёзды небесные, Господа, / пойте и превозносите Его вовеки. на 14:"},
  {"id": "ru-pes-0230", "section": "service", "who": "reader", "text": "Благословляйте, всякий дождь и роса, все ветры, Господа, / пойте и превозносите Его вовеки. Ирмос"},
  {"id": "ru-pes-0231", "section": "service", "who": "reader", "text": "Благословляйте, огонь и жар, холод и зной, Господа, / пойте и превозносите Его вовеки. на 12:"},
  {"id": "ru-pes-0232", "section": "service", "who": "reader", "text": "Благословляйте, инеи и снега, ночи и дни, Господа, / пойте и превозносите Его вовеки."},
  {"id": "ru-pes-0233", "section": "service", "who": "reader", "text": "Благословляйте, свет и тьма, молнии и облака, Господа, / пойте и превозносите Его вовеки. на 10:"},
  {"id": "ru-pes-0234", "section": "service", "who": "reader", "text": "Благословляйте земля, горы и холмы, и всё произрастающее на земле, Господа, / пойте и превозносите Его вовеки."},
  {"id": "ru-pes-0235", "section": "service", "who": "reader", "text": "Благословляйте, источники, моря и реки, киты и всё, движущееся в водах, Господа, / пойте и превозносите Его вовеки. на 8:"},
  {"id": "ru-pes-0236", "section": "service", "who": "reader", "text": "Благословляйте, все птицы небесные, звери и весь скот, Господа, / пойте и превозносите Его вовеки."},
  {"id": "ru-pes-0237", "section": "service", "who": "reader", "text": "Благословляйте, сыны человеческие, / да благословляет Израиль Господа, / пойте и превозносите Его вовеки. на 6:"},
  {"id": "ru-pes-0238", "section": "service", "who": "reader", "text": "Благословляйте, священники Господни, рабы Господни, Господа, / пойте и превозносите Его вовеки."},
  {"id": "ru-pes-0239", "section": "service", "who": "reader", "text": "Благословляйте, духи и души праведных, / благоговейные и смиренные сердцем, Господа, / пойте и превозносите Его вовеки. на 4:"},
  {"id": "ru-pes-0240", "section": "service", "who": "reader", "text": "Благословляйте, Анания, Азария и Мисаил, Господа, / пойте и превозносите Его вовеки. Дан 3:57, 58, 60, 62, 64, 66, 67, 70-88"},
  {"id": "ru-pes-0241", "section": "service", "who": "reader", "text": "Благословляйте, Апостолы, пророки и мученики Господни, Господа, / пойте и превозносите Его вовеки."},
  {"id": "ru-pes-0242", "section": "service", "who": "reader", "text": "Благословим Отца, и Сына, и Святого Духа Господа."},
  {"id": "ru-pes-0243", "section": "service", "who": "reader", "text": "И ныне, и всегда и вовеки веков. Аминь."},
  {"id": "ru-pes-0244", "section": "service", "who": "reader", "text": "Хвалим, благословляем, поклоняемся Господу, воспевая и превознося Его во все века. Катавасия"},
  {"id": "ru-pes-0245", "section": "service", "who": "rubric", "text": "Песнь 9"},
  {"id": "ru-pes-0246", "section": "service", "who": "reader", "text": "Величает душа Моя Господа, / и возрадовался дух Мой о Боге, Спасителе Моём."},
  {"id": "ru-pes-0247", "section": "service", "who": "reader", "text": "Честью высшую Херувимов / и несравненно славнейшую Серафимов, / девственно Бога-Слово родившую, / истинную Богородицу – Тебя величаем."},
  {"id": "ru-pes-0248", "section": "service", "who": "rubric", "text": "– повторяем после каждого стиха."},
  {"id": "ru-pes-0249", "section": "service", "who": "reader", "text": "Что призрел Он на смирение Рабы Своей; / ибо отныне назовут Меня блаженной все роды."},
  {"id": "ru-pes-0250", "section": "service", "who": "reader", "text": "Что сотворил Мне великое Сильный, / и свято имя Его, / и милость Его в роды родов к боящимся Его."},
  {"id": "ru-pes-0251", "section": "service", "who": "reader", "text": "Соделал Он сильное рукою Своею, / рассеял надменных в помышлениях сердца их."},
  {"id": "ru-pes-0252", "section": "service", "who": "reader", "text": "Низложил властителей с престолов / и вознёс смиренных, / алчущих исполнил благ / и богатых отослал ни с чем."},
  {"id": "ru-pes-0253", "section": "service", "who": "reader", "text": "Поддержал Израиля, отрока Своего, вспомнив о милости, – / как Он сказал отцам нашим, – / к Аврааму и семени его навеки. Лк 1:46–55"},
  {"id": "ru-pes-0254", "section": "service", "who": "rubric", "text": "Ирмос. Тропарь первый без стиха."},
  {"id": "ru-pes-0255", "section": "service", "who": "rubric", "text": "на 12:"},
  {"id": "ru-pes-0256", "section": "service", "who": "reader", "text": "Благословен Господь, Бог Израилев, / что посетил и сотворил искупление народу Своему."},
  {"id": "ru-pes-0257", "section": "service", "who": "reader", "text": "И воздвиг рог спасения нам / в доме Давида, отрока Своего. на 10:"},
  {"id": "ru-pes-0258", "section": "service", "who": "reader", "text": "Как Он сказал устами святых, бывших от века пророков Своих, – / спасение от врагов наших / и от руки всех ненавидящих нас."},
  {"id": "ru-pes-0259", "section": "service", "who": "reader", "text": "Сотворить милость отцам нашим / и вспомнить завет Свой святой. на 8:"},
  {"id": "ru-pes-0260", "section": "service", "who": "reader", "text": "Клятву, которою Он клялся Аврааму, отцу нашему, / дать нам безбоязненно, от рук врагов наших избавившимся."},
  {"id": "ru-pes-0261", "section": "service", "who": "reader", "text": "Служить Ему в святости и правде / пред Ним во все дни жизни нашей. на 6:"},
  {"id": "ru-pes-0262", "section": "service", "who": "reader", "text": "И ты, дитя, пророком Всевышнего будешь названо, / ибо ты будешь идти пред лицом Господа – приготовить пути Ему."},
  {"id": "ru-pes-0263", "section": "service", "who": "reader", "text": "Дать народу Его познать спасение / в отпущении грехов их, / по глубине милосердия Бога нашего. на 4:"},
  {"id": "ru-pes-0264", "section": "service", "who": "reader", "text": "Которым с высоты посетит нас Восходящее Светило, / чтобы воссиять сидящим во тьме и тени смертной."},
  {"id": "ru-pes-0265", "section": "service", "who": "reader", "text": "Направить ноги наши на путь мира. Лк 1:68–79"},
  {"id": "ru-pes-0266", "section": "service", "who": "reader", "text": "Слава: И ныне: Катавасия"},
  {"id": "ru-pes-0267", "section": "service", "who": "rubric", "text": "Песни священного писания исполняемые великим постом"},
  {"id": "ru-pes-0268", "section": "service", "who": "rubric", "text": "Песнь 1"},
  {"id": "ru-pes-0269", "section": "service", "who": "reader", "text": "Воспоём Господу, ибо Он славно прославился; / коня и всадника ввергнул в море."},
  {"id": "ru-pes-0270", "section": "service", "who": "reader", "text": "Помощник и Покровитель стал мне спасением; / Он – Бог мой, и прославлю Его, / Бог отца моего, и превознесу Его."},
  {"id": "ru-pes-0271", "section": "service", "who": "reader", "text": "Господь, сокрушающий в битвах, / Господь – имя Ему. / Колесницы фараона и войско его ввергнул Он в море."},
  {"id": "ru-pes-0272", "section": "service", "who": "reader", "text": "И отборных конных военачальников / потопил в Красном море."},
  {"id": "ru-pes-0273", "section": "service", "who": "reader", "text": "Пучиною покрыл их, / они погрузились в глубину, как камень."},
  {"id": "ru-pes-0274", "section": "service", "who": "reader", "text": "Десница Твоя, Господи, прославилась силою; / правая рука Твоя, Господи, сломила врагов, / и множеством славы Твоей Ты сокрушил противников."},
  {"id": "ru-pes-0275", "section": "service", "who": "reader", "text": "Послал гнев Твой, он пожрал их, как солому, / и духом ярости Твоей расступилась вода. на 14:"},
  {"id": "ru-pes-0276", "section": "service", "who": "reader", "text": "Застыли воды, как стена, / застыли и волны посреди моря. Ирмос"},
  {"id": "ru-pes-0277", "section": "service", "who": "reader", "text": "Сказал враг: «Погонюсь, настигну, / разделю добычу, насыщу душу мою, / убью мечём моим, господствовать будет рука моя». на 12:"},
  {"id": "ru-pes-0278", "section": "service", "who": "reader", "text": "Ты послал Дух Твой, покрыло их море, / погрузились они, как свинец, в воде великой."},
  {"id": "ru-pes-0279", "section": "service", "who": "reader", "text": "Кто подобен Тебе среди богов, Господи? / Кто подобен Тебе, прославленный среди святых, / дивный в славе, творящий чудеса. на 10:"},
  {"id": "ru-pes-0280", "section": "service", "who": "reader", "text": "Ты простер десницу Твою, – / поглотила их земля. / Ты повёл по правде Твоей этот народ Твой, который Ты искупил."},
  {"id": "ru-pes-0281", "section": "service", "who": "reader", "text": "Призвал силою Твоею во обитель святую Твою. / Услышали народы, и разгневались, / муки объяли жителей Филистимских. на 8:"},
  {"id": "ru-pes-0282", "section": "service", "who": "reader", "text": "Тогда заспешили вожди Эдома / и князья Моавитян, объял их трепет, / изнемогли все жители Ханаана."},
  {"id": "ru-pes-0283", "section": "service", "who": "reader", "text": "Да нападёт на них страх и трепет; / от величия мышцы Твоей да станут они, как камень. на 6:"},
  {"id": "ru-pes-0284", "section": "service", "who": "reader", "text": "Доколе не пройдёт народ Твой, Господи, / доколе не пройдёт народ Твой сей, который Ты приобрёл."},
  {"id": "ru-pes-0285", "section": "service", "who": "reader", "text": "Введи и насади их на горе наследия Твоего, / в готовое жилище Твоё, которое устроил Ты, Господи, / святыню, Господи, которую приготовили руки Твои. на 4:"},
  {"id": "ru-pes-0286", "section": "service", "who": "reader", "text": "Господь царствует вечно: и навек, и дальше. / Когда вошел конь фараона с колесницами и всадниками в море."},
  {"id": "ru-pes-0287", "section": "service", "who": "reader", "text": "И навёл на них Господь воду морскую, / сыны же Израилевы прошли по суше посреди моря. Исх 15:1–19"},
  {"id": "ru-pes-0288", "section": "service", "who": "reader", "text": "Слава: И ныне:"},
  {"id": "ru-pes-0289", "section": "service", "who": "reader", "text": "Слава Тебе, Боже наш, слава Тебе."},
  {"id": "ru-pes-0290", "section": "service", "who": "rubric", "text": "Песнь 2"},
  {"id": "ru-pes-0291", "section": "service", "who": "reader", "text": "Внимай, небо, и я буду говорить, / и да услышит земля слова уст моих."},
  {"id": "ru-pes-0292", "section": "service", "who": "reader", "text": "Пусть ждут, как дождя, изречения моего, / и да сойдут, как роса, речи мои."},
  {"id": "ru-pes-0293", "section": "service", "who": "reader", "text": "Как ливень на траву, / и как вьюга на луг. / Ибо я имя Господне призвал: / воздайте величие Богу нашему!"},
  {"id": "ru-pes-0294", "section": "service", "who": "reader", "text": "Бог, истины дела Его, / и все пути Его – суд."},
  {"id": "ru-pes-0295", "section": "service", "who": "reader", "text": "Бог верен, и нет неправды в Нём, / праведен и свят Господь."},
  {"id": "ru-pes-0296", "section": "service", "who": "reader", "text": "Они согрешили, не Его дети, порочные, / род строптивый и развращенный; / это так вы Господу воздаёте?"},
  {"id": "ru-pes-0297", "section": "service", "who": "reader", "text": "Народ глупый и несмысленный. / Не Сам ли Он, Отец твой, приобрёл тебя, / и создал тебя и сотворил тебя?"},
  {"id": "ru-pes-0298", "section": "service", "who": "reader", "text": "Вспомните дни вечные, / уразумейте годы рода родов."},
  {"id": "ru-pes-0299", "section": "service", "who": "reader", "text": "Спроси отца твоего – и возвестит он тебе, / старших тебя – и они скажут тебе."},
  {"id": "ru-pes-0300", "section": "service", "who": "reader", "text": "Когда Всевышний разделял племена, / когда рассеял сынов Адамовых."},
  {"id": "ru-pes-0301", "section": "service", "who": "reader", "text": "Он поставил пределы племён / по числу Ангелов Божиих. / И сделался долей Господа народ Его Иаков, / уделом наследия Его – Израиль."},
  {"id": "ru-pes-0302", "section": "service", "who": "reader", "text": "Он дал ему довольство в пустыне, / при жажде от зноя в безводной."},
  {"id": "ru-pes-0303", "section": "service", "who": "reader", "text": "Окружил его и наставил его, / и сохранил его, как зеницу ока."},
  {"id": "ru-pes-0304", "section": "service", "who": "reader", "text": "Как орёл прикрывает гнездо своё, / и стремится к птенцам своим."},
  {"id": "ru-pes-0305", "section": "service", "who": "reader", "text": "Распростерши крылья принимает их, / и берет их на спину свою."},
  {"id": "ru-pes-0306", "section": "service", "who": "reader", "text": "Так Господь один их повёл, / и не было с ними бога чужого."},
  {"id": "ru-pes-0307", "section": "service", "who": "reader", "text": "Он возвёл их на неприступное место земли, / напитал их произведениями полей."},
  {"id": "ru-pes-0308", "section": "service", "who": "reader", "text": "Напились они мёда из камня / и елея из твёрдой скалы."},
  {"id": "ru-pes-0309", "section": "service", "who": "reader", "text": "Масла коровьего и молока овец, / с туком ягнят и овнов, / молодых быков и козлов, / с лучшей тучной пшеницей, / и пили кровь виноградных ягод – вино."},
  {"id": "ru-pes-0310", "section": "service", "who": "reader", "text": "И поел Иаков, и насытился, / и отвернулся, возлюбленный."},
  {"id": "ru-pes-0311", "section": "service", "who": "reader", "text": "Растолстел, разжирел, раздался / и оставил Бога, создавшего его, / и отступил от Бога, Спасителя своего."},
  {"id": "ru-pes-0312", "section": "service", "who": "reader", "text": "Они раздражили Меня чуждыми, / мерзостями своими огорчили Меня."},
  {"id": "ru-pes-0313", "section": "service", "who": "reader", "text": "Приносили жертвы демонам, а не Богу, / богам, которых не знали, – / новые они, и пришли недавно, / те, которых не знали отцы их."},
  {"id": "ru-pes-0314", "section": "service", "who": "reader", "text": "Бога, родившего тебя, ты оставил, / и забыл Бога, питающего тебя."},
  {"id": "ru-pes-0315", "section": "service", "who": "reader", "text": "И увидел Господь и возревновал, / и возмутился от гнева на сынов Своих и дочерей."},
  {"id": "ru-pes-0316", "section": "service", "who": "reader", "text": "И сказал: «Отвращу лицо Моё от них, / и покажу, что будет им напоследок»."},
  {"id": "ru-pes-0317", "section": "service", "who": "reader", "text": "Ибо они род извращённый, / сыны, у которых верности нет."},
  {"id": "ru-pes-0318", "section": "service", "who": "reader", "text": "Они возбудили во Мне ревность не-богом, / идолами своими рассердили Меня."},
  {"id": "ru-pes-0319", "section": "service", "who": "reader", "text": "И Я возбужу в них ревность не-народом, / народом неразумным рассержу их."},
  {"id": "ru-pes-0320", "section": "service", "who": "reader", "text": "Ибо огонь зажжён от гнева Моего, / гореть будет до ада глубочайшего."},
  {"id": "ru-pes-0321", "section": "service", "who": "reader", "text": "Поест землю и произведения её, / опалит основания гор."},
  {"id": "ru-pes-0322", "section": "service", "who": "reader", "text": "Соберу на них бедствия / и стрелы Мои истощу на них."},
  {"id": "ru-pes-0323", "section": "service", "who": "reader", "text": "Изнурит их голод и станут пищей для птиц, / и согнет их неисцелимо."},
  {"id": "ru-pes-0324", "section": "service", "who": "reader", "text": "Зубы зверей пошлю на них / вместе с яростью пресмыкающихся по земле."},
  {"id": "ru-pes-0325", "section": "service", "who": "reader", "text": "Извне меч лишит их детей, / и из внутренних покоев – страх; / падут юноша с девою, / грудное дитя с глубоким старцем."},
  {"id": "ru-pes-0326", "section": "service", "who": "reader", "text": "Я сказал: «Рассею их, / прекращу у людей память о них»."},
  {"id": "ru-pes-0327", "section": "service", "who": "reader", "text": "Если бы не гнев врагов, чтобы не были они долговечны, / и чтобы не налегли вместе противники."},
  {"id": "ru-pes-0328", "section": "service", "who": "reader", "text": "Не сказали: «Рука наша высока, / и не Господь всё это сделал»."},
  {"id": "ru-pes-0329", "section": "service", "who": "reader", "text": "Ибо это народ, потерявший рассудок, / и нет среди них знания."},
  {"id": "ru-pes-0330", "section": "service", "who": "reader", "text": "Не размыслили, чтобы понять это, – / пусть же воспримут в грядущее время."},
  {"id": "ru-pes-0331", "section": "service", "who": "reader", "text": "Как бы один преследовал тысячи / и двое прогнали бы десятки тысяч, –"},
  {"id": "ru-pes-0332", "section": "service", "who": "reader", "text": "Если бы Бог не отдал их, / и Господь не предал их!"},
  {"id": "ru-pes-0333", "section": "service", "who": "reader", "text": "Ведь боги их не как Бог наш, / а враги наши – безумны."},
  {"id": "ru-pes-0334", "section": "service", "who": "reader", "text": "Ведь от лозы Содомской виноград их, / и отрасль их – из Гоморры."},
  {"id": "ru-pes-0335", "section": "service", "who": "reader", "text": "Ягода их – ягода со вкусом желчи, / гроздья горькие у них."},
  {"id": "ru-pes-0336", "section": "service", "who": "reader", "text": "Ярость драконов – вино их / и ярость аспидов неисцелимая."},
  {"id": "ru-pes-0337", "section": "service", "who": "reader", "text": "Вот, не всё ли это собрано у Меня, / и не запечатано ли в хранилищах Моих?"},
  {"id": "ru-pes-0338", "section": "service", "who": "reader", "text": "В день отмщения Я воздам."},
  {"id": "ru-pes-0339", "section": "service", "who": "reader", "text": "Во время, когда поскользнётся нога их."},
  {"id": "ru-pes-0340", "section": "service", "who": "reader", "text": "Ибо близко день гибели их, / рядом приготовленное вам!"},
  {"id": "ru-pes-0341", "section": "service", "who": "reader", "text": "Ибо судить будет Господь народ Свой, / и над рабами Своими смилуется."},
  {"id": "ru-pes-0342", "section": "service", "who": "reader", "text": "Ибо Он увидит их бессильными, / и оставленными в напасти, и изнемогшими."},
  {"id": "ru-pes-0343", "section": "service", "who": "reader", "text": "И сказал Господь: «Где боги их, / те, на которых полагались они, / те, тук чьих жертв вы ели, / и пили вино возлияний их?»"},
  {"id": "ru-pes-0344", "section": "service", "who": "reader", "text": "Пусть они восстанут и помогут вам, / и сделаются вам защитниками."},
  {"id": "ru-pes-0345", "section": "service", "who": "reader", "text": "Видите, видите, что Я есмь, / и нет бога кроме Меня."},
  {"id": "ru-pes-0346", "section": "service", "who": "reader", "text": "Я умерщвлю и оживотворю, / Я поражу и Я исцелю, / и нет того, кто отнимет из рук Моих."},
  {"id": "ru-pes-0347", "section": "service", "who": "reader", "text": "Ибо подниму Я к небу руку Мою, / и поклянусь десницей Моей / и скажу: «Живу Я вовек!»"},
  {"id": "ru-pes-0348", "section": "service", "who": "reader", "text": "Ибо заострю, как молнию, меч Мой, / и возьмется за суд рука Моя."},
  {"id": "ru-pes-0349", "section": "service", "who": "reader", "text": "И воздам наказание врагам, / и ненавидящим Меня воздам."},
  {"id": "ru-pes-0350", "section": "service", "who": "reader", "text": "Напою стрелы Мои кровью, / и меч Мой пожирать будет плоть."},
  {"id": "ru-pes-0351", "section": "service", "who": "reader", "text": "Кровь раненых и пленных, / головы вождей языческих."},
  {"id": "ru-pes-0352", "section": "service", "who": "reader", "text": "Возвеселитесь, небеса, вместе с Ним, / и да поклонятся Ему все Ангелы Божии."},
  {"id": "ru-pes-0353", "section": "service", "who": "reader", "text": "Возвеселитесь, язычники, с народом Его, / и да укрепятся в Нём все сыны Божии."},
  {"id": "ru-pes-0354", "section": "service", "who": "reader", "text": "Ибо отмщается кровь сынов Его, / и отмстит Он, и воздаст наказание врагам, / и ненавидящим Его воздаст."},
  {"id": "ru-pes-0355", "section": "service", "who": "reader", "text": "И очистит Господь землю народа Своего. Втор 32:1–43"},
  {"id": "ru-pes-0356", "section": "service", "who": "reader", "text": "Слава: И ныне: Слава Тебе, Боже наш, слава Тебе."},
  {"id": "ru-pes-0357", "section": "service", "who": "rubric", "text": "Песнь 3"},
  {"id": "ru-pes-0358", "section": "service", "who": "reader", "text": "Утвердилось сердце моё в Господе, / вознесся рог мой в Боге моём, / широко раскрылись на врагов моих уста мои: / я радуюсь о спасении Твоём."},
  {"id": "ru-pes-0359", "section": "service", "who": "reader", "text": "Ибо нет святого, как Господь, / и нет праведного, как Бог наш, / и нет святого, кроме Тебя."},
  {"id": "ru-pes-0360", "section": "service", "who": "reader", "text": "Не хвалитесь и не говорите высокого в гордыне, / речь надменная да не выйдет из уст ваших."},
  {"id": "ru-pes-0361", "section": "service", "who": "reader", "text": "Ибо Бог ведения Господь, / и Бог, уготовляющий дела Свои. на 14:"},
  {"id": "ru-pes-0362", "section": "service", "who": "reader", "text": "Лук сильных ослабел, / а немощные препоясались силою. Ирмос"},
  {"id": "ru-pes-0363", "section": "service", "who": "reader", "text": "Насыщенные хлебом оскудели, / а алчущие заселили землю. на 12:"},
  {"id": "ru-pes-0364", "section": "service", "who": "reader", "text": "Ибо неплодная родила семерых, / а многодетная изнемогла."},
  {"id": "ru-pes-0365", "section": "service", "who": "reader", "text": "Господь умерщвляет и животворит, / низводит во ад и возводит. на 10:"},
  {"id": "ru-pes-0366", "section": "service", "who": "reader", "text": "Господь делает нищим и обогащает, / унижает и возвышает, / поднимает с земли бедного, / и из грязи воздвигает нищего."},
  {"id": "ru-pes-0367", "section": "service", "who": "reader", "text": "Чтобы посадить его с властителями народа, / и престол славы давая в наследие ему. на 8:"},
  {"id": "ru-pes-0368", "section": "service", "who": "reader", "text": "Дает молитву молящемуся / и благословляет годы праведного."},
  {"id": "ru-pes-0369", "section": "service", "who": "reader", "text": "Ибо не мощью силен муж. / Господь сделает немощным противника Своего, / Господь свят. на 6:"},
  {"id": "ru-pes-0370", "section": "service", "who": "reader", "text": "Да не хвалится мудрый мудростью своею, / и да не хвалится сильный силою своею, / и да не хвалится богатый богатством своим."},
  {"id": "ru-pes-0371", "section": "service", "who": "reader", "text": "Но лишь тем да хвалится хвалящийся, / что разумеет и знает Господа / и творит суд и правду посреди земли. на 4:"},
  {"id": "ru-pes-0372", "section": "service", "who": "reader", "text": "Господь взошёл на небеса и возгремел, / Он, праведный, будет судить концы земли."},
  {"id": "ru-pes-0373", "section": "service", "who": "reader", "text": "И даст мощь царю нашему, / и возвысит рог помазанника Своего. 1 Цар 2:1–10"},
  {"id": "ru-pes-0374", "section": "service", "who": "reader", "text": "Слава: И ныне: Слава Тебе, Боже наш, слава Тебе."},
  {"id": "ru-pes-0375", "section": "service", "who": "rubric", "text": "Песнь 4"},
  {"id": "ru-pes-0376", "section": "service", "who": "reader", "text": "Господи, услышал я весть Твою – и убоялся, / уразумел дела Твои – и изумился."},
  {"id": "ru-pes-0377", "section": "service", "who": "reader", "text": "Посреди двух живых существ Ты будешь узнан, / когда приблизятся годы, будешь познан, / когда наступит срок – показан, / когда смущена душа моя – во гневе вспомнишь о милости."},
  {"id": "ru-pes-0378", "section": "service", "who": "reader", "text": "Бог от Фемана придёт, / и Святой – от горы [Фаран,] осененной чащей."},
  {"id": "ru-pes-0379", "section": "service", "who": "reader", "text": "Покрыла небеса доблесть Его / и хвалы Его полна земля."},
  {"id": "ru-pes-0380", "section": "service", "who": "reader", "text": "И сияние Его будет как свет: / роги в руках Его, / и приготовил Он крепкую любовь силы Своей."},
  {"id": "ru-pes-0381", "section": "service", "who": "reader", "text": "Пред лицом Его пойдет слово / и выйдет на равнины по следам Его."},
  {"id": "ru-pes-0382", "section": "service", "who": "reader", "text": "Он встал – и поколебалась земля, / взглянул – и изнемогли народы."},
  {"id": "ru-pes-0383", "section": "service", "who": "reader", "text": "Сокрушены были горы силою, / расплавлены холмы вечные, / от вечных шествий Его за труды узрел я."},
  {"id": "ru-pes-0384", "section": "service", "who": "reader", "text": "Жилища Эфиопов, устрашатся / и шатры земли Мадиамской."},
  {"id": "ru-pes-0385", "section": "service", "who": "reader", "text": "Разве на реки прогневался Ты, Господи, / или на реки – ярость Твоя, / или на море – стремление Твоё."},
  {"id": "ru-pes-0386", "section": "service", "who": "reader", "text": "Что Ты взойдешь на коней Твоих, / и езда Твоя – спасение?"},
  {"id": "ru-pes-0387", "section": "service", "who": "reader", "text": "Напрягая, натянешь лук Твой / против скипетров, говорит Господь."},
  {"id": "ru-pes-0388", "section": "service", "who": "reader", "text": "От рек рассечена будет земля; / увидят Тебя и будут мучиться народы."},
  {"id": "ru-pes-0389", "section": "service", "who": "reader", "text": "Разгоняя воды при шествии, / подала бездна голос свой, / высота – явления свои."},
  {"id": "ru-pes-0390", "section": "service", "who": "reader", "text": "Поднялось солнце, / и луна стала на месте своём."},
  {"id": "ru-pes-0391", "section": "service", "who": "reader", "text": "В свете копья Твои полетят, / в сиянии блеска доспехов Твоих."},
  {"id": "ru-pes-0392", "section": "service", "who": "reader", "text": "Угрозою Твоей Ты умалишь землю, / и в ярости низложишь народы."},
  {"id": "ru-pes-0393", "section": "service", "who": "reader", "text": "Ты вышел для спасения народа Твоего, / спасти помазанников Твоих. на 14:"},
  {"id": "ru-pes-0394", "section": "service", "who": "reader", "text": "Бросил в головы беззаконных смерть, / воздвиг им узы до шеи. Ирмос"},
  {"id": "ru-pes-0395", "section": "service", "who": "reader", "text": "Рассек в исступлении головы властителей; / они содрогнутся при сем: / раскроют узды свои, / как нищий, поедающий скрытно. на 12:"},
  {"id": "ru-pes-0396", "section": "service", "who": "reader", "text": "И возвёл Ты на море коней Твоих, / волнующих воды многие."},
  {"id": "ru-pes-0397", "section": "service", "who": "reader", "text": "Я укрылся, и устрашилась внутренность моя / от гласа молитвы губ моих. на 10:"},
  {"id": "ru-pes-0398", "section": "service", "who": "reader", "text": "И вошел трепет в кости мои, / и во мне сотряслась крепость моя."},
  {"id": "ru-pes-0399", "section": "service", "who": "reader", "text": "Отдохну я в день скорби моей, / чтобы придти мне к народу, с которым странствую я. на 8:"},
  {"id": "ru-pes-0400", "section": "service", "who": "reader", "text": "Ибо смоковница не принесёт плода, / и не будет плода на виноградных лозах."},
  {"id": "ru-pes-0401", "section": "service", "who": "reader", "text": "Обманет произведение маслины, / и поля не принесут пищи. на 6:"},
  {"id": "ru-pes-0402", "section": "service", "who": "reader", "text": "Без еды остались овцы, / и нет волов у яслей."},
  {"id": "ru-pes-0403", "section": "service", "who": "reader", "text": "Я же возрадуюсь о Господе, / возвеселюсь в Боге, Спасителе моём. на 4:"},
  {"id": "ru-pes-0404", "section": "service", "who": "reader", "text": "Господь, Бог мой – сила моя, / и направит Он ноги мои к совершенству."},
  {"id": "ru-pes-0405", "section": "service", "who": "reader", "text": "И на высоты возведёт меня, / чтобы победить мне, воспевая Его. Авв 3:1–19"},
  {"id": "ru-pes-0406", "section": "service", "who": "reader", "text": "Слава: И ныне: Слава Тебе, Боже наш, слава Тебе."},
  {"id": "ru-pes-0407", "section": "service", "who": "rubric", "text": "Песнь 5"},
  {"id": "ru-pes-0408", "section": "service", "who": "reader", "text": "От ночи с рассвета стремится дух мой к Тебе, Боже, / ибо свет – повеления Твои на земле."},
  {"id": "ru-pes-0409", "section": "service", "who": "reader", "text": "Правде научитесь, живущие на земле. / Ведь обуздан нечестивец; не научится он правде, / на земле истины не сотворит."},
  {"id": "ru-pes-0410", "section": "service", "who": "reader", "text": "Пусть сгинет нечестивец, да не видит славы Господа. / Господи, высока Твоя мышца, и они не познали; / но, уразумев, устыдятся. на 14:"},
  {"id": "ru-pes-0411", "section": "service", "who": "reader", "text": "Ревность постигнет народ не наставленный, / и ныне противников поглотит огонь. Ирмос"},
  {"id": "ru-pes-0412", "section": "service", "who": "reader", "text": "Господи, Боже наш, мир дай нам, / ибо всё Ты воздал нам. на 12:"},
  {"id": "ru-pes-0413", "section": "service", "who": "reader", "text": "Господи Боже наш, возьми во владение нас; / Господи, кроме Тебя, мы иного не знаем, / имя Твоё именуем."},
  {"id": "ru-pes-0414", "section": "service", "who": "reader", "text": "А мёртвые жизни не увидят, / и врачи их не воскресят. на 10:"},
  {"id": "ru-pes-0415", "section": "service", "who": "reader", "text": "Потому Ты навел гнев, и погубил, / и уничтожил весь мужской пол их."},
  {"id": "ru-pes-0416", "section": "service", "who": "reader", "text": "Прибавь бедствий им, Господи, / прибавь бедствий славным земли. на 8:"},
  {"id": "ru-pes-0417", "section": "service", "who": "reader", "text": "Господи, в скорби я вспомнил Тебя, / в скорби краткой вразумление Твоё нам."},
  {"id": "ru-pes-0418", "section": "service", "who": "reader", "text": "И как рождающая приближается к родам / и в муке своей возопила, / так мы стали для Возлюбленного Твоего. на 6:"},
  {"id": "ru-pes-0419", "section": "service", "who": "reader", "text": "По страху пред Тобою, Господи, мы приняли во чреве, / и помучились, и родили: / Дух спасения Твоего произвели на земле."},
  {"id": "ru-pes-0420", "section": "service", "who": "reader", "text": "Не падём, но падут живущие на земле. на 4:"},
  {"id": "ru-pes-0421", "section": "service", "who": "reader", "text": "Воскреснут мёртвые, и восстанут находящиеся в гробницах, / и возвеселятся живущие на земле."},
  {"id": "ru-pes-0422", "section": "service", "who": "reader", "text": "Ибо роса, что от Тебя, – исцеление для них, / земля же нечестивых падёт. Ис 26:9–19"},
  {"id": "ru-pes-0423", "section": "service", "who": "reader", "text": "Слава: И ныне: Слава Тебе, Боже наш, слава Тебе."},
  {"id": "ru-pes-0424", "section": "service", "who": "rubric", "text": "Песнь 6"},
  {"id": "ru-pes-0425", "section": "service", "who": "rubric", "text": "Ирмос"},
  {"id": "ru-pes-0426", "section": "service", "who": "reader", "text": "Возопил я в скорби моей к Господу, Богу моему, / и Он услышал меня; на 12:"},
  {"id": "ru-pes-0427", "section": "service", "who": "reader", "text": "Из чрева ада вопль мой: / Ты услышал голос мой. / Ты отринул меня в глубины, в сердце моря, / и реки окружили меня."},
  {"id": "ru-pes-0428", "section": "service", "who": "reader", "text": "Все валы Твои и волны Твои прошли надо мною. на 10:"},
  {"id": "ru-pes-0429", "section": "service", "who": "reader", "text": "И я сказал: «Отвергнут я от очей Твоих. / Придётся ли мне ещё взглянуть на храм святой Твой?"},
  {"id": "ru-pes-0430", "section": "service", "who": "reader", "text": "Разлилась вокруг меня вода до души моей, / окружила меня бездна глубочайшая. на 8:"},
  {"id": "ru-pes-0431", "section": "service", "who": "reader", "text": "Погрузилась голова моя в расселины гор, / сошёл я в землю, чьи засовы – преграды вечные."},
  {"id": "ru-pes-0432", "section": "service", "who": "reader", "text": "Но да взойдёт от гибели жизнь моя к Тебе, Господи, Боже мой. на 6:"},
  {"id": "ru-pes-0433", "section": "service", "who": "reader", "text": "Когда оставляла меня душа моя, вспомнил я Господа."},
  {"id": "ru-pes-0434", "section": "service", "who": "reader", "text": "И да придет к Тебе молитва моя, в храм святой Твой. на 4:"},
  {"id": "ru-pes-0435", "section": "service", "who": "reader", "text": "Соблюдающие суетное и ложное милость свою оставили."},
  {"id": "ru-pes-0436", "section": "service", "who": "reader", "text": "Я же со гласом хвалы и славословия принесу жертву Тебе, / всё, что обещал, воздам Тебе, о спасении моём – Господу. Ион 2:3–10"},
  {"id": "ru-pes-0437", "section": "service", "who": "reader", "text": "Слава: И ныне: Слава Тебе, Боже наш, слава Тебе."},
  {"id": "ru-pes-0438", "section": "service", "who": "rubric", "text": "Песнь 7"},
  {"id": "ru-pes-0439", "section": "service", "who": "reader", "text": "Благословен Ты, Господи Боже отцов наших, / и хвально и прославлено имя Твое вовеки."},
  {"id": "ru-pes-0440", "section": "service", "who": "reader", "text": "Ибо праведен Ты во всем, что соделал с нами."},
  {"id": "ru-pes-0441", "section": "service", "who": "reader", "text": "И все дела Твои истинны, и правы пути Твои, / и все суды Твои истинны."},
  {"id": "ru-pes-0442", "section": "service", "who": "reader", "text": "И суды истинные Ты сотворил во всём, что навёл на нас / и на святой град отцов наших Иерусалим."},
  {"id": "ru-pes-0443", "section": "service", "who": "reader", "text": "Потому что по истине и по суду навёл Ты всё это на нас за грехи наши."},
  {"id": "ru-pes-0444", "section": "service", "who": "reader", "text": "Ибо согрешили мы, и поступили беззаконно, / отступив от Тебя, и погрешили во всём."},
  {"id": "ru-pes-0445", "section": "service", "who": "reader", "text": "И заповедей Твоих не послушали, и не соблюли, и не соделали, / как Ты повелел нам, чтобы благо нам было."},
  {"id": "ru-pes-0446", "section": "service", "who": "reader", "text": "И всё, что Ты навёл на нас, и всё, что Ты соделал с нами, / соделал по истинному суду."},
  {"id": "ru-pes-0447", "section": "service", "who": "reader", "text": "И предал нас в руки врагов беззаконных, / враждебнейших отступников, / и царю неправедному и злейшему на всей земле."},
  {"id": "ru-pes-0448", "section": "service", "who": "reader", "text": "И ныне не открыть нам уст; / мы сделались стыдом и поношением для рабов Твоих и чтущих Тебя."},
  {"id": "ru-pes-0449", "section": "service", "who": "reader", "text": "Не предай же нас до конца ради имени Твоего, / и не разрушь завета Твоего, / и не удали милости Твоей от нас / ради Авраама, возлюбленного Тобою, / и ради Исаака, раба Твоего, / и Израиля, святого Твоего."},
  {"id": "ru-pes-0450", "section": "service", "who": "reader", "text": "Которым Ты сказал, говоря им, / что умножишь семя их, как звёзды небесные / и как песок на берегу моря."},
  {"id": "ru-pes-0451", "section": "service", "who": "reader", "text": "Ибо мы умалились, Владыка, более всех народов, / и унижены сегодня на всей земле за грехи наши."},
  {"id": "ru-pes-0452", "section": "service", "who": "reader", "text": "И нет у нас в настоящее время ни князя, ни пророка, / ни вождя, ни всесожжения, ни жертвы, / ни приношения, ни фимиама, / ни места, чтобы нам принести плоды пред лицо Твоё и обрести милость."},
  {"id": "ru-pes-0453", "section": "service", "who": "reader", "text": "Но с душою сокрушённою и духом смирения да будем приняты."},
  {"id": "ru-pes-0454", "section": "service", "who": "reader", "text": "Как при всесожжении овнов и тельцов / и как при десятках тысяч агнцев тучных, / так да сделается жертва наша пред Тобою сегодня, / и да совершится для Тебя, – / ибо нет стыда уповающим на Тебя."},
  {"id": "ru-pes-0455", "section": "service", "who": "reader", "text": "И ныне мы следуем за Тобою всем сердцем, / и боимся Тебя, и ищем лица Твоего."},
  {"id": "ru-pes-0456", "section": "service", "who": "reader", "text": "Не постыди нас, но сотвори с нами по снисхождению Твоему / и по множеству милости Твоей."},
  {"id": "ru-pes-0457", "section": "service", "who": "reader", "text": "И избавь нас силою чудес Твоих, / и дай славу имени Твоему, Господи."},
  {"id": "ru-pes-0458", "section": "service", "who": "reader", "text": "И да посрамятся все, делающие рабам Твоим зло, / и да постыдятся со всею силою и могуществом, / и мощь их да сокрушится."},
  {"id": "ru-pes-0459", "section": "service", "who": "reader", "text": "И да познают, что Ты, Господи, Бог единый / и славный по всей вселенной."},
  {"id": "ru-pes-0460", "section": "service", "who": "reader", "text": "И не переставали ввергшие их слуги царя / разжигать печь нефтью, смолою, паклею и хворостом. на 14:"},
  {"id": "ru-pes-0461", "section": "service", "who": "reader", "text": "И поднимался пламень над печью на сорок девять локтей. Ирмос"},
  {"id": "ru-pes-0462", "section": "service", "who": "reader", "text": "И вырывался, и сжигал тех из Халдеев, / которых достигал около печи. на 12:"},
  {"id": "ru-pes-0463", "section": "service", "who": "reader", "text": "Но Ангел Господень сошел в печь вместе с Азарией и бывшими с ним."},
  {"id": "ru-pes-0464", "section": "service", "who": "reader", "text": "И выбросил пламень огня из печи. на 10:"},
  {"id": "ru-pes-0465", "section": "service", "who": "reader", "text": "И сделал, что в средине печи был как бы шумящий влажный ветер, / и огонь нисколько не прикоснулся к ним, и не повредил им, и не смутил их."},
  {"id": "ru-pes-0466", "section": "service", "who": "reader", "text": "Тогда сии трое, как бы одними устами, воспели в печи, / и благословили и прославили Бога: на 8:"},
  {"id": "ru-pes-0467", "section": "service", "who": "reader", "text": "Благословен Ты, Господи, Боже отцов наших, / и хвальный и превозносимый вовеки."},
  {"id": "ru-pes-0468", "section": "service", "who": "reader", "text": "И благословенно имя славы Твоей, святое / и прехвальное и превозносимое вовеки. на 6:"},
  {"id": "ru-pes-0469", "section": "service", "who": "reader", "text": "Благословен Ты в храме святой славы Твоей, / и прехвальный и преславный вовеки."},
  {"id": "ru-pes-0470", "section": "service", "who": "reader", "text": "Благословен Ты, видящий бездны, восседающий на Херувимах, / и прехвальный и превозносимый вовеки. на 4:"},
  {"id": "ru-pes-0471", "section": "service", "who": "reader", "text": "Благословен Ты на престоле славы Царства Твоего, / и прехвальный и превозносимый вовеки."},
  {"id": "ru-pes-0472", "section": "service", "who": "reader", "text": "Благословен Ты на тверди небесной, / и прехвальный и преславный вовеки. Дан 3:26–56"},
  {"id": "ru-pes-0473", "section": "service", "who": "reader", "text": "Слава: И ныне: Слава Тебе, Боже наш, слава Тебе."},
  {"id": "ru-pes-0474", "section": "service", "who": "rubric", "text": "Песнь 8"},
  {"id": "ru-pes-0475", "section": "service", "who": "reader", "text": "Благословляйте, все творения Господни, Господа, / пойте и превозносите Его вовеки."},
  {"id": "ru-pes-0476", "section": "service", "who": "reader", "text": "Благословляйте, Ангелы Господни, небеса Господни, Господа, / пойте и превозносите Его вовеки."},
  {"id": "ru-pes-0477", "section": "service", "who": "reader", "text": "Благословляйте, все воды, что превыше небес, все силы Господни, Господа, / пойте и превозносите Его вовеки."},
  {"id": "ru-pes-0478", "section": "service", "who": "reader", "text": "Благословляйте, солнце и луна, звёзды небесные, Господа, / пойте и превозносите Его вовеки."},
  {"id": "ru-pes-0479", "section": "service", "who": "reader", "text": "Благословляйте, всякий дождь и роса, все ветры, Господа, / пойте и превозносите Его вовеки. на 14:"},
  {"id": "ru-pes-0480", "section": "service", "who": "reader", "text": "Благословляйте, огонь и жар, холод и зной, Господа, / пойте и превозносите Его вовеки. Ирмос"},
  {"id": "ru-pes-0481", "section": "service", "who": "reader", "text": "Благословляйте, росы и вьюги, лёд и мороз, Господа, / пойте и превозносите Его вовеки. на 12:"},
  {"id": "ru-pes-0482", "section": "service", "who": "reader", "text": "Благословляйте, инеи и снега, ночи и дни, Господа, / пойте и превозносите Его вовеки."},
  {"id": "ru-pes-0483", "section": "service", "who": "reader", "text": "Благословляйте, свет и тьма, молнии и облака, Господа, / пойте и превозносите Его вовеки. на 10:"},
  {"id": "ru-pes-0484", "section": "service", "who": "reader", "text": "Благословляйте земля, горы и холмы, Господа, / пойте и превозносите Его вовеки."},
  {"id": "ru-pes-0485", "section": "service", "who": "reader", "text": "Благословляйте, источники, моря и реки, киты и всё, движущееся в водах, Господа, / пойте и превозносите Его вовеки. на 8:"},
  {"id": "ru-pes-0486", "section": "service", "who": "reader", "text": "Благословляйте, все птицы небесные, звери и весь скот, Господа, / пойте и превозносите Его вовеки."},
  {"id": "ru-pes-0487", "section": "service", "who": "reader", "text": "Благословляйте, сыны человеческие, / да благословляет Израиль Господа, / пойте и превозносите Его вовеки. на 6:"},
  {"id": "ru-pes-0488", "section": "service", "who": "reader", "text": "Благословляйте, священники Господни, рабы Господни, Господа, / пойте и превозносите Его вовеки."},
  {"id": "ru-pes-0489", "section": "service", "who": "reader", "text": "Благословляйте, духи и души праведных, / благоговейные и смиренные сердцем, Господа, / пойте и превозносите Его вовеки. на 4:"},
  {"id": "ru-pes-0490", "section": "service", "who": "reader", "text": "Благословляйте, Анания, Азария и Мисаил, Господа, / пойте и превозносите Его вовеки. Дан 3:57–88"},
  {"id": "ru-pes-0491", "section": "service", "who": "reader", "text": "Благословляйте, Апостолы, пророки и мученики Господни, Господа, / пойте и превозносите Его вовеки."},
  {"id": "ru-pes-0492", "section": "service", "who": "reader", "text": "Благословим Отца, и Сына, и Святого Духа Господа."},
  {"id": "ru-pes-0493", "section": "service", "who": "reader", "text": "И ныне, и всегда и вовеки веков. Аминь."},
  {"id": "ru-pes-0494", "section": "service", "who": "reader", "text": "Слава Тебе, Боже наш, слава Тебе."},
  {"id": "ru-pes-0495", "section": "service", "who": "reader", "text": "Хвалим, благословляем, поклоняемся Господу, воспевая и превознося Его во все века."},
  {"id": "ru-pes-0496", "section": "service", "who": "rubric", "text": "Песнь 9"},
  {"id": "ru-pes-0497", "section": "service", "who": "reader", "text": "Величает душа Моя Господа, / и возрадовался дух Мой о Боге, Спасителе Моём."},
  {"id": "ru-pes-0498", "section": "service", "who": "reader", "text": "Честью высшую Херувимов / и несравненно славнейшую Серафимов, / девственно Бога-Слово родившую, / истинную Богородицу – Тебя величаем."},
  {"id": "ru-pes-0499", "section": "service", "who": "rubric", "text": "– повторяем после каждого стиха."},
  {"id": "ru-pes-0500", "section": "service", "who": "reader", "text": "Что призрел Он на смирение Рабы Своей; / ибо отныне назовут Меня блаженной все роды."},
  {"id": "ru-pes-0501", "section": "service", "who": "reader", "text": "Что сотворил Мне великое Сильный, / и свято имя Его, / и милость Его в роды родов к боящимся Его."},
  {"id": "ru-pes-0502", "section": "service", "who": "reader", "text": "Соделал Он сильное рукою Своею, / рассеял надменных в помышлениях сердца их."},
  {"id": "ru-pes-0503", "section": "service", "who": "reader", "text": "Низложил властителей с престолов / и вознёс смиренных, / алчущих исполнил благ / и богатых отослал ни с чем."},
  {"id": "ru-pes-0504", "section": "service", "who": "reader", "text": "Поддержал Израиля, отрока Своего, вспомнив о милости, – / как Он сказал отцам нашим, – / к Аврааму и семени его навеки. Лк 1:46–55 Ирмос на 12:"},
  {"id": "ru-pes-0505", "section": "service", "who": "reader", "text": "Благословен Господь, Бог Израилев, / что посетил и сотворил искупление народу Своему."},
  {"id": "ru-pes-0506", "section": "service", "who": "reader", "text": "И воздвиг рог спасения нам / в доме Давида, отрока Своего."},
  {"id": "ru-pes-0507", "section": "service", "who": "reader", "text": "Как Он сказал устами святых, бывших от века пророков Своих. на 10:"},
  {"id": "ru-pes-0508", "section": "service", "who": "reader", "text": "Спасение от врагов наших / и от руки всех ненавидящих нас."},
  {"id": "ru-pes-0509", "section": "service", "who": "reader", "text": "Сотворить милость отцам нашим / и вспомнить завет Свой святой. на 8:"},
  {"id": "ru-pes-0510", "section": "service", "who": "reader", "text": "Клятву, которою Он клялся Аврааму, отцу нашему, / дать нам безбоязненно, от рук врагов наших избавившимся."},
  {"id": "ru-pes-0511", "section": "service", "who": "reader", "text": "Служить Ему в святости и правде / пред Ним во все дни жизни нашей. на 6:"},
  {"id": "ru-pes-0512", "section": "service", "who": "reader", "text": "И ты, дитя, пророком Всевышнего будешь названо, / ибо ты будешь идти пред лицом Господа – приготовить пути Ему."},
  {"id": "ru-pes-0513", "section": "service", "who": "reader", "text": "Дать народу Его познать спасение / в отпущении грехов их, / по глубине милосердия Бога нашего. на 4:"},
  {"id": "ru-pes-0514", "section": "service", "who": "reader", "text": "Которым с высоты посетит нас Восходящее Светило, / чтобы воссиять сидящим во тьме и тени смертной."},
  {"id": "ru-pes-0515", "section": "service", "who": "reader", "text": "Направить ноги наши на путь мира. Лк 1:68–79"},
  {"id": "ru-pes-0516", "section": "service", "who": "reader", "text": "Слава: И ныне: Слава Тебе, Боже наш, слава Тебе."},
];

